from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        first_index = {}
        for i, x in enumerate(elements):
            if x <= max_group and x not in first_index:
                first_index[x] = i

        best = [INF] * (max_group + 1)

        for x, idx in first_index.items():
            for multiple in range(x, max_group + 1, x):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [best[g] if best[g] != INF else -1 for g in groups]
